import pandas as pd
import numpy as np

# Load data
df_transport = pd.read_csv("chunks_csv/getisord/getisord_2022_transport.csv")
df_adj = pd.read_csv(ADJACENCY_PATH)

# Build undirected adjacency list
adj = {}
# Initialize keys for all boroughs
for b in df_transport['borough']:
    adj[b] = set()
# Populate adjacency
for _, row in df_adj.iterrows():
    b, n = row['borough'], row['neighbor']
    if b in adj:
        adj[b].add(n)
    else:
        adj[b] = {n}
    if n in adj:
        adj[n].add(b)
    else:
        adj[n] = {b}

# Create a series for fast lookup
transport_series = df_transport.set_index('borough')['Transport_value']

# Compute local sums
local_sums = {}
for b in transport_series.index:
    own = transport_series.loc[b]
    # If own is missing skip it
    if pd.isna(own):
        continue
    neighs = adj.get(b, set())
    neigh_vals = transport_series.reindex(neighs).dropna()
    local_sum = own + neigh_vals.sum()
    local_sums[b] = local_sum

# Global distribution of local sums
sums = np.array(list(local_sums.values()))
mean_s = sums.mean()
std_s = sums.std(ddof=0)

# Compute z-scores
results = {}
for b, s in local_sums.items():
    z = (s - mean_s) / std_s
    results[b] = z

# Identify hot and cold spots at 95% level (|z| > 1.96)
spots = []
for b, z in results.items():
    if z > 1.96:
        spots.append((b, "HOT", z))
    elif z < -1.96:
        spots.append((b, "COLD", z))

# Format final answer
if not spots:
    output = "FINAL ANSWER: none"
else:
    formatted = ", ".join([f"{b} ({kind}, z-score = {z:.3f})" for b, kind, z in spots])
    output = f"FINAL ANSWER: {formatted}"

print(output)
